actions.action:
// Physical nexus established - MN filing required
// Apportionment will be calculated by federal tables 7000-7500
// MN uses single-sales factor apportionment

// Economic nexus established per Wayfair - MN filing required
// Threshold: $100,000 gross receipts OR 200 transactions
// Apportionment calculated by federal tables 7000-7500

// No nexus - no MN filing required
apportionment.state_tax = 0.0;
apportionment.state_refund_or_owed = apportionment.state_payments;

            // Calculate Minnesota state additions
            double additions = 0.0;

            // Add back federal bond interest (taxable to MN)
            // Note: Would need revenue.federal_bond_interest field
            // additions += revenue.federal_bond_interest;

            // Add back IRC 199A deduction (MN doesn't conform)
            // Note: Would need result.section_199a_deduction field
            // additions += result.section_199a_deduction;

            // Add back foreign dividend deduction (IRC 245A, 250)
            // Note: Would need result.foreign_dividend_deduction field
            // additions += result.foreign_dividend_deduction;

            apportionment.state_additions = additions;

            // Calculate Minnesota state subtractions
            double subtractions = 0.0;

            // Subtract Minnesota municipal bond interest
            // Note: Would need revenue.mn_municipal_interest field
            // subtractions += revenue.mn_municipal_interest;

            // Subtract small business income deduction (if applicable)
            // Note: Would need to calculate based on MN criteria
            // subtractions += result.mn_small_business_deduction;

            // Subtract Minnesota NOL deduction
            // Note: MN has 80% limitation like federal but may have different rules
            // subtractions += result.mn_nol_carryforward;

            apportionment.state_subtractions = subtractions;

            // Minnesota uses 9.5% flat rate (as of 2024)
            // Simplified from previous progressive bracket structure
            apportionment.state_tax =
              apportionment.state_taxable_income * apportionment.state_tax_rate;

            // Subtract Minnesota state credits
            apportionment.state_tax =
              Math.max(0.0, apportionment.state_tax - apportionment.state_credits);

            // Calculate refund or amount owed
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;
